  public async void Import(string[] paths) {Diagnostics.Log("subtitle.import",new{Paths=paths});
   if(IsBusy){Status("请先等待当前操作结束，再添加字幕。");return;}Status("正在读取字幕…");var all=await Task.Run(()=> {var result=new List<string>();var pending=new Stack<string>(paths);while(pending.Count>0) {var p=pending.Pop();try {if(File.Exists(p)&&System.IO.Path.GetExtension(p).Equals(".srt",StringComparison.OrdinalIgnoreCase))result.Add(System.IO.Path.GetFullPath(p));else if(Directory.Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)==0) {foreach(var f in Directory.GetFiles(p,"*.srt"))result.Add(f);foreach(var d in Directory.GetDirectories(p))pending.Push(d);}}catch {}}return result;});
   if(closed)return;int added=0;var errors=new List<string>();foreach(var p in all) {if(files.Any(x=>x.Path.Equals(p,StringComparison.OrdinalIgnoreCase)))continue;try {var file=await Task.Run(()=>SubtitleIO.Read(p));if(files.Any(x=>x.Path.Equals(p,StringComparison.OrdinalIgnoreCase)))continue;file.VideoPath=FindVideo(p);files.Add(file);added++;}catch(Exception ex) {errors.Add(System.IO.Path.GetFileName(p)+"："+ex.Message);}}
   Status("已添加 "+added+" 集字幕。"+(errors.Count>0?"读取失败："+string.Join("；",errors):"请选择剧本并配置 API。"));if(Get<DataGrid>("SubtitleFiles").SelectedItem==null&&files.Count>0)Get<DataGrid>("SubtitleFiles").SelectedIndex=0;
  }
  string FindVideo(string srt) {var candidates=videoPaths();try {candidates=candidates.Concat(Directory.GetFiles(System.IO.Path.GetDirectoryName(srt)).Where(x=>new[]{".mp4",".mov",".mkv",".avi",".webm",".m4v",".wmv"}.Contains(System.IO.Path.GetExtension(x).ToLowerInvariant()))).Distinct(StringComparer.OrdinalIgnoreCase).ToList();}catch {}var exact=candidates.Where(x=>System.IO.Path.GetFileNameWithoutExtension(x).Equals(System.IO.Path.GetFileNameWithoutExtension(srt),StringComparison.OrdinalIgnoreCase)).ToList();if(exact.Count==1)return exact[0];var episode=candidates.Where(x=>SubtitleIO.Episode(x)==SubtitleIO.Episode(srt)).ToList();return episode.Count==1?episode[0]:null;}
  public async void LoadScript(string file) {if(IsBusy)return;scriptLoading=true;Busy(true);try {var text=await Task.Run(()=>SubtitleIO.Script(file));if(string.IsNullOrWhiteSpace(text))throw new IOException("剧本没有可读取的文本。");script=text;scriptPath=Path.GetFullPath(file);Diagnostics.Log("subtitle.script_loaded",new{File=scriptPath,Characters=text.Length,Hash=ProjectStore.TextHash(text)});Get<TextBox>("ScriptPathBox").Text=scriptPath;undo.Clear();Nouns.Clear();Get<TextBlock>("ScriptInfo").Text="剧本："+System.IO.Path.GetFileName(file)+" · "+script.Length+" 字符";Get<TextBlock>("ScriptInfo").ToolTip=file;Get<TextBlock>("NounCount").Text="名词表：0 项";foreach(var f in files) {f.Completed=false;f.ManualReview=null;f.Issues.Clear();f.Status="待校对";foreach(var cue in f.Cues){cue.Corrected=null;cue.ReviewState=-1;cue.Refresh();}f.Refresh();}Select(current);Status("剧本已加载。可先提取并审核名词表，也可直接开始校对。");}catch(Exception ex) {Status("读取剧本失败："+ex.Message);}finally{scriptLoading=false;Busy(cancel!=null);}}
  void UpdateApiInfo() {Get<TextBlock>("ApiInfo").Text="模型："+(api.Model.Length==0?"未选择":api.Model)+" · 仅校对专有名词，不将台词差异当错字。";}
  void Select(SubtitleFile file) {if(file!=current&&subFrameStrip!=null)subFrameStrip.Close();current=file;Get<DataGrid>("SubtitleIssues").ItemsSource=file==null?null:file.Issues;Get<DataGrid>("Cues").ItemsSource=file==null?null:file.Cues;Get<DataGrid>("SubtitleIssues").Items.Refresh();Get<DataGrid>("Cues").Items.Refresh();Get<TextBlock>("CueTitle").Text=file==null?"字幕内容":file.Name+" · "+file.Cues.Count+" 条";LoadVideo();if(file!=null&&file.Issues.Count>0){var target=file.Issues[0];if(Get<DataGrid>("SubtitleIssues").SelectedItem==target)ShowCue(target.Cue,target);else Get<DataGrid>("SubtitleIssues").SelectedItem=target;}else if(file!=null&&file.Cues.Count>0){var cue=file.Cues[0];if(Get<DataGrid>("Cues").SelectedItem==cue)ShowCue(cue,null);else Get<DataGrid>("Cues").SelectedItem=cue;}}
  void LoadVideo() {playing=false;if(previewCancel!=null)previewCancel.Cancel();Get<MediaElement>("SubPlayer").Close();Get<Image>("SubStill").Source=null;Get<Image>("SubStill").Visibility=Visibility.Visible;var label=Get<TextBlock>("SubPreviewMessage");label.Visibility=Visibility.Visible;label.Text="可自动关联同名／同集视频，也可手动关联";Get<TextBlock>("LinkedVideo").Text=current==null?"未关联视频":current.VideoName;}
  async void ShowCue(Cue cue,SubtitleIssue issue) {if(current==null)return;if(Get<DataGrid>("Cues").SelectedItem!=cue)Get<DataGrid>("Cues").SelectedItem=cue;Get<DataGrid>("Cues").ScrollIntoView(cue);Get<TextBlock>("CueOriginal").Text="原文："+cue.Original.Replace('\n',' ');Get<TextBlock>("CueEvidence").Text=issue==null?"剧本出处：选择名词疑点查看":("剧本出处："+(issue.Evidence??"待定位"));Get<TextBlock>("CueSuggestion").Text=issue==null?"当前："+cue.Text.Replace('\n',' '):"建议："+issue.OriginalTerm+" → "+issue.SuggestedTerm+" · "+issue.Reason;
   playing=false;Get<MediaElement>("SubPlayer").Close();await PreviewAt(cue.Start);
