  async Task PreviewAt(double time) {subPosition=time;if(current==null||string.IsNullOrEmpty(current.VideoPath))return;if(previewCancel!=null)previewCancel.Cancel();previewCancel=new CancellationTokenSource();previewCancel.CancelAfter(20000);var token=previewCancel.Token;string file=current.VideoPath;Get<Image>("SubStill").Visibility=Visibility.Visible;try {var data=await Task.Run(()=>Detector.Preview(file,time,token));if(closed||token.IsCancellationRequested)return;var bitmap=new BitmapImage();using(var ms=new MemoryStream(data)) {bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=ms;bitmap.EndInit();bitmap.Freeze();}Get<Image>("SubStill").Source=bitmap;Get<TextBlock>("SubPreviewMessage").Visibility=Visibility.Collapsed;}catch(OperationCanceledException) {}catch(Exception ex) {if(!closed)Status("视频定位未完成："+ex.Message);}}
  void Busy(bool busy) {foreach(var n in new[]{"ImportSrt","ImportSrtFolder","PickScript","ApiSettings","ExtractNouns","EditNouns","CheckNouns","RemoveSrt","ClearAllSrt","ImportNouns","LoadScriptPath","UndoChange","AcceptOne","AcceptCertain","SaveSrt"})Get<Button>(n).IsEnabled=!busy;Get<Button>("CancelCheck").IsEnabled=cancel!=null;Get<TextBox>("ScriptPathBox").IsEnabled=!busy;}
  async Task Run(bool extractOnly) {
   if(IsBusy)return;if(script.Length==0){Status("请先选择剧本文件。");return;}if(string.IsNullOrWhiteSpace(api.Model)){Status("请先配置 API 与模型。");return;}if(!extractOnly&&files.Count==0){Status("请先添加每集 SRT。");return;}
   bool multi=Get<CheckBox>("MultiDialogs").IsChecked==true;int batchFiles=5,dialogs=2;if(multi&&(!int.TryParse(Get<TextBox>("BatchFiles").Text,out batchFiles)||batchFiles<1||batchFiles>100||!int.TryParse(Get<TextBox>("DialogCount").Text,out dialogs)||dialogs<1||dialogs>16)){Status("每组文件数请输入 1–100，并发对话数请输入 1–16。");return;}
   try{api.BaseUrl();}catch(Exception ex){Status(ex.Message);return;}var selected=Get<DataGrid>("SubtitleFiles").SelectedItems.Cast<SubtitleFile>().ToList();var queue=selected.Count>1?selected:Get<DataGrid>("SubtitleFiles").Items.Cast<SubtitleFile>().ToList();bool extract=extractOnly||Nouns.Count==0;int extractUnits=extract?NounChecker.Chunks(script).Count:0,extractDone=0;var done=queue.ToDictionary(f=>f.Path,f=>0);var sizes=queue.ToDictionary(f=>f.Path,f=>BatchCount(f));int total=extractUnits+(extractOnly?0:sizes.Values.Sum());cancel=new CancellationTokenSource();var token=cancel.Token;Busy(true);SetProgress(0,total,"准备校对");
   Action<Action> ui=action=>{if(owner.Dispatcher.CheckAccess())action();else owner.Dispatcher.BeginInvoke(action);};Action<string> extractProgress=message=>ui(()=>{Log(message);var m=Regex.Match(message,@"(\d+)\s*/\s*(\d+)\s*$");if(m.Success)SetProgress(int.Parse(m.Groups[1].Value)-1,total,"提取剧本名词");});
   var extractor=new AiClient(api);extractor.Trace=message=>ui(()=>Log(message));try {
    if(extract){var nouns=await NounChecker.Extract(script,extractor,extractProgress,token);if(nouns.Count==0)throw new IOException("未提取到专有名词，请手动补充名词表。");await Task.Run(()=>ScriptEvidence.Enrich(nouns,script));Nouns=nouns;extractDone=extractUnits;Get<TextBlock>("NounCount").Text="名词表："+Nouns.Count+" 项";SetProgress(extractDone,total,"名词提取完成");Log("名词提取完成，共 "+Nouns.Count+" 项，已记录剧本出处。");}
    if(extractOnly){SetProgress(total,total,"名词提取完成");Status("名词表已更新，可查看出处并补充合法称呼。");return;}
    undo.RemoveAll(x=>queue.Any(f=>f.Path==x.File));foreach(var f in queue){f.Completed=false;f.ManualReview=null;f.Issues=new List<SubtitleIssue>();f.Status="排队中";foreach(var cue in f.Cues){cue.Corrected=null;cue.ReviewState=-1;cue.Refresh();}f.Refresh();}if(current!=null&&queue.Contains(current))Select(current);
    var groups=new List<List<SubtitleFile>>();int per=multi?batchFiles:Math.Max(1,queue.Count);for(int i=0;i<queue.Count;i+=per)groups.Add(queue.Skip(i).Take(per).ToList());int next=-1,failed=0,finished=0;int concurrency=multi?Math.Min(dialogs,groups.Count):1;Status("开始校对："+queue.Count+" 集，"+groups.Count+" 组，并发 "+concurrency+"。"+(multi?"多对话会重复携带名词表，可能增加 token 消耗。":""));
    Func<Task> worker=async()=>{while(!token.IsCancellationRequested){int group=Interlocked.Increment(ref next);if(group>=groups.Count)return;string tag="对话组 "+(group+1)+"/"+groups.Count;var client=new AiClient(api){ConversationTag=tag};client.Trace=message=>ui(()=>Log(tag+" · "+message));Log(tag+" 开始，包含 "+groups[group].Count+" 集");foreach(var f in groups[group]){token.ThrowIfCancellationRequested();f.Status="校对中";f.Refresh();Action<string> progress=message=>ui(()=>{Log(tag+" · "+message);var m=Regex.Match(message,@"(\d+)\s*/\s*(\d+)\s*$");if(m.Success)done[f.Path]=Math.Max(0,int.Parse(m.Groups[1].Value)-1);SetProgress(extractDone+done.Values.Sum(),total,"正在处理 "+f.Name);});try{var findings=await NounChecker.Check(f,Nouns,client,progress,token);ScriptEvidence.Attach(findings,Nouns,f.Name);f.Issues=findings;f.Completed=true;f.Status=findings.Count==0?"未发现名词问题":"发现名词疑点";foreach(var cue in f.Cues){cue.ReviewState=0;cue.Refresh();}foreach(var finding in findings){finding.Cue.ReviewState=Math.Max(finding.Cue.ReviewState,finding.State);finding.Cue.Refresh();}finished++;Log(tag+" · 完成 "+f.Name+"，"+findings.Count+" 项疑点");}catch(OperationCanceledException){f.Status="已停止";f.Refresh();throw;}catch(Exception ex){failed++;f.Status="校对失败";f.Completed=false;Log(tag+" · 失败 "+f.Name+"："+ex.Message);}done[f.Path]=sizes[f.Path];f.Refresh();if(current==f)Select(f);SetProgress(extractDone+done.Values.Sum(),total,"已结束 "+(finished+failed)+"/"+queue.Count+" 集（失败 "+failed+"）");NotifyChanged();}Log(tag+" 已结束");}};
    await Task.WhenAll(Enumerable.Range(0,Math.Max(1,concurrency)).Select(i=>worker()));SetProgress(total,total,"处理结束：成功 "+finished+"，失败 "+failed);Status("名词校对结束：成功 "+finished+" 集，失败 "+failed+" 集，共 "+queue.Where(f=>f.Completed).Sum(f=>f.Issues.Count)+" 项疑点。");
   }catch(OperationCanceledException){Status("已停止，完成的集数与结果保留，可查看日志。");}catch(Exception ex){Status("校对未完成："+ex.Message);}finally{foreach(var f in queue.Where(x=>x.Status=="排队中")){f.Status="待校对";f.Refresh();}if(!closed){cancel.Dispose();cancel=null;Busy(false);NotifyChanged();}}
  }
  void EditNouns() {var text=string.Join("\r\n",Nouns.Select(n=>n.Canonical+" | "+n.Aliases+" | "+n.Category));var dialog=new Window {Owner=owner,Title="审核名词表",Width=620,Height=520,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=owner.Background,Foreground=owner.Foreground,FontFamily=owner.FontFamily};dialog.Resources.MergedDictionaries.Add(owner.Resources);var grid=new Grid {Margin=new Thickness(15)};grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});var hint=new TextBlock {Text="每行：标准名词 | 可接受别称（用顿号分隔） | 类型\n合法简称、昵称将被保留；可手动补充名词。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)};var box=new TextBox {Text=text,AcceptsReturn=true,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};var save=new Button {Content="保存名词表",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};Grid.SetRow(box,1);Grid.SetRow(save,2);grid.Children.Add(hint);grid.Children.Add(box);grid.Children.Add(save);save.Click+=(s,e)=> {var list=new List<Noun>();foreach(var line in box.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)) {var parts=line.Split('|');if(parts[0].Trim().Length>0)list.Add(new Noun {Canonical=parts[0].Trim(),Aliases=parts.Length>1?parts[1].Trim():"",Category=parts.Length>2?parts[2].Trim():"手动"});}Nouns=list.GroupBy(x=>x.Canonical).Select(x=>x.First()).ToList();ScriptEvidence.Enrich(Nouns,script);NotifyChanged();Get<TextBlock>("NounCount").Text="名词表："+Nouns.Count+" 项";dialog.Close();};dialog.Content=grid;dialog.ShowDialog();}
  void RefreshCueState(Cue cue) {if(current==null)return;var list=current.Issues.Where(x=>x.Cue==cue).ToList();cue.ReviewState=list.Count==0?0:list.Any(x=>x.State==1)?1:list.Any(x=>x.State==2)?2:0;cue.Refresh();}
  bool Accept(SubtitleIssue issue) {if(issue.Accepted)return false;var text=issue.Cue.Corrected??issue.Cue.Original;if(!text.Contains(issue.OriginalTerm)) {Status("这条字幕已发生其他修改，请先核对当前正文。");return false;}RecordUndo(issue);issue.Cue.Corrected=text.Replace(issue.OriginalTerm,issue.SuggestedTerm);issue.Accepted=true;issue.State=0;issue.Refresh();RefreshCueState(issue.Cue);if(current!=null)current.Refresh();ShowCue(issue.Cue,issue);Status("已在内存中采纳名词建议，需点击“另存校对版 SRT”保存。");return true;}
  void Save() {if(files.Count==0)return;using(var d=new System.Windows.Forms.FolderBrowserDialog {Description="选择校对版 SRT 的另存文件夹，原文件不会覆盖"}) {if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;int count=0;foreach(var f in files.Where(x=>x.Completed||x.Cues.Any(c=>c.Corrected!=null))) {string file=System.IO.Path.Combine(d.SelectedPath,System.IO.Path.GetFileNameWithoutExtension(f.Path)+"_名词校对.srt");int version=2;while(File.Exists(file))file=System.IO.Path.Combine(d.SelectedPath,System.IO.Path.GetFileNameWithoutExtension(f.Path)+"_名词校对-"+(version++)+".srt");File.WriteAllText(file,f.ExportText(),new UTF8Encoding(true));count++;}Status("已另存 "+count+" 集字幕（UTF-8）；时间轴、序号及原文件保留。");}}
  void Export() {if(files.Count==0)return;var d=new SaveFileDialog {Title="导出名词校对报告",Filter="CSV 表格|*.csv|完整 JSON|*.json",FileName="名词校对报告-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")};if(d.ShowDialog(owner)!=true)return;try {var rows=files.SelectMany(f=>f.Issues.Select(x=>new {File=f.Name,Video=f.VideoPath,Number=x.Number,Start=x.Cue.Start,End=x.Cue.End,OriginalTerm=x.OriginalTerm,SuggestedTerm=x.SuggestedTerm,Reason=x.Reason,State=x.State,Accepted=x.Accepted,Original=x.Cue.Original,Current=x.Cue.Text})).ToList();if(d.FilterIndex==2)File.WriteAllText(d.FileName,Util.Json().Serialize(new {Script=scriptPath,Nouns=Nouns,Files=files.Select(f=>new {f.Name,f.VideoPath,f.RunStatus,f.Completed,f.ReviewState}),Issues=rows}),new UTF8Encoding(false));else {var sb=new StringBuilder("字幕文件,关联视频,字幕序号,开始时间,结束时间,原名词,建议名词,原因,审核状态,是否采纳,原文,当前正文\r\n");foreach(var r in rows)sb.AppendLine(string.Join(",",new[]{r.File,r.Video,r.Number.ToString(),Util.Time(r.Start),Util.Time(r.End),r.OriginalTerm,r.SuggestedTerm,r.Reason,r.State==0?"通过":r.State==1?"有错":"存疑",r.Accepted?"已采纳":"未采纳",r.Original,r.Current}.Select(x=>"\""+(x??"").Replace("\"","\"\"")+"\"")));File.WriteAllText(d.FileName,sb.ToString(),new UTF8Encoding(true));}Status("报告已导出。");}catch(Exception ex) {Status("导出失败："+ex.Message);}}
  public void Close() {closed=true;if(subFrameStrip!=null)subFrameStrip.Close();playing=false;subRevealing=false;if(cancel!=null)cancel.Cancel();if(previewCancel!=null)previewCancel.Cancel();timer.Stop();Get<MediaElement>("SubPlayer").Close();}
  public async void Pause() {bool wasPlaying=playing;double time=Get<MediaElement>("SubPlayer").Position.TotalSeconds;if(wasPlaying)subPosition=time;playing=false;subRevealing=false;Get<MediaElement>("SubPlayer").Close();if(wasPlaying&&!closed)await PreviewAt(time);}
 }
